function personExportPanel(){
 return `<article class="card"><h2>Personen · OnCall-Beispielexport</h2><p>Erzeugt eine Beispieldatei im Aufbau der gelieferten OnCall-Personendatei. Enthält auch die geschäftliche Adresse. Geburtsdatum, Geschlecht und Kürzel sind nicht erforderlich und bleiben leer. Personen- und Abteilungskennungen müssen vor der echten Anbindung abgeglichen werden. Es erfolgt keine Übermittlung.</p><button id="new-person-export" type="button">Personen-Beispielexport erzeugen</button>${[...(state.person_exports||[])].reverse().map(e=>`<section class="person-export-record"><h3>${esc(e.filename)}</h3><p class="small muted">${esc(swissTime(e.created_at))} · ${e.person_count} Personen · Beispieldatei erzeugt</p><a href="/api/oncall/person-exports/${esc(e.id)}">JSON herunterladen</a><details class="export-preview" data-person-export-preview="${esc(e.id)}"><summary>Datei ansehen</summary><pre aria-label="Inhalt der OnCall-Personendatei"></pre></details>${e.warnings.length?`<details class="export-preview"><summary>Offene Angaben und Zuordnungen (${e.warnings.length} Personen)</summary>${e.warnings.map(w=>`<p><b>${esc(name(w.employee_id))}</b><br>${w.issues.map(esc).join('<br>')}</p>`).join('')}</details>`:''}</section>`).join('')}</article>`;
}
function auditPresentation(value){
 if(Array.isArray(value))return value.map(auditPresentation);
 if(!value||typeof value!=='object')return value;
 const out={};
 for(const [key,item] of Object.entries(value)){
   if(['id','assignment_id','export_id','external_id','scope_id','favorite_id'].includes(key))continue;
   if(key==='employee_id'){out.Person=name(item);continue;}
   if(key==='function_id'){out.Funktion=functionName(item);continue;}
   if(key==='group_ids'){out.Gruppen=item.map(groupName);continue;}
   if(key==='group_id'){out.Gruppe=groupName(item)||'Keine Gruppe';continue;}
   if(key==='department_id'){out.Abteilung=state.departments.find(d=>d.id===item)?.name||'Keine Abteilung';continue;}
   if(key==='geodependency'||key==='geo_id'){out.Gebiet=item?regionName(item):'Ortsunabhängig / allgemein';continue;}
   if(key==='geo_ids'||key==='region_ids'){out.Gebiete=Array.isArray(item)?item.map(regionName):'Alle Regionen';continue;}
   if(key==='covers'){out.Gebietsabdeckung=Object.fromEntries(Object.entries(item).map(([whole,parts])=>[regionName(whole),parts.map(regionName)]));continue;}
   out[key]=auditPresentation(item);
 }
 return out;
}
